SELECT
    COUNT(*)
FROM trip_mission
WHERE trip_id = #{tripId}
  AND trip_mission_id = #{tripMissionId}
  AND status = 'IN_PROGRESS'

SELECT
    COUNT(*)
FROM member_rel_trip
WHERE trip_id = #{tripId}
  AND member_id = #{memberId}
  AND status = 'JOINED'

SELECT
    COUNT(*)
FROM setlog
WHERE trip_mission_id = #{tripMissionId}
  AND member_id = #{memberId}
  AND deleted_at IS NULL
